1|import "server-only";
2|
3|// Reads image env once per request. Any missing key means unavailable:
4|// with no quotas or budget configured, the route must never spend.
5|export interface ImageEnv {
6|  upstashUrl: string;
7|  upstashToken: string;
8|  metaKey: string;
9|  sessionSecret: string;
10|  ipSalt: string;
11|  spendCapMicro: number;
12|  dailySpendCapMicro: number;
13|}
14|
15|// Vercel's Upstash marketplace integration injects KV_REST_API_* names.
16|// UPSTASH_* wins when non-empty, else the KV_* fallback applies per value.
17|// The read-only token is never used (we write).
18|const URL_NAMES = "UPSTASH_REDIS_REST_URL|KV_REST_API_URL";
19|const TOKEN_NAMES = "UPSTASH_REDIS_REST_TOKEN|KV_REST_API_TOKEN";
20|
21|const REQUIRED = [
22|  "BLOB_READ_WRITE_TOKEN",
23|  "META_API_KEY",
24|  "SESSION_SECRET",
25|  "IP_HASH_SALT",
26|] as const;
27|
28|// One rule for both caps: a finite, non-negative USD value wins,
29|// anything else (missing, blank, non-numeric, negative, Infinity) falls back.
30|// Zero stays valid so a zero cap can intentionally block spend.
31|function parseCapUsd(raw: string | undefined, fallback: number): number {
32|  if (raw === undefined || raw.trim() === "") return fallback;
33|  const value = Number(raw);
34|  return Number.isFinite(value) && value >= 0 ? value : fallback;
35|}
36|
37|export function readImageEnv(from: NodeJS.ProcessEnv = process.env): ImageEnv {
38|  const upstashUrl = from.UPSTASH_REDIS_REST_URL || from.KV_REST_API_URL;
39|  const upstashToken = from.UPSTASH_REDIS_REST_TOKEN || from.KV_REST_API_TOKEN;
40|  const missing = [
41|    upstashUrl ? null : URL_NAMES,
42|    upstashToken ? null : TOKEN_NAMES,
43|    ...REQUIRED.filter((k) => !from[k]),
44|  ].filter((m): m is string => m !== null);
45|  if (missing.length > 0) throw new Error(`missing image env: ${missing.join(",")}`);
46|  return {
47|    upstashUrl: upstashUrl as string,
48|    upstashToken: upstashToken as string,
49|    metaKey: from.META_API_KEY as string,
50|    sessionSecret: from.SESSION_SECRET as string,
51|    ipSalt: from.IP_HASH_SALT as string,
52|    spendCapMicro: Math.round(parseCapUsd(from.SPEND_CAP_USD, 10) * 1_000_000),
53|    dailySpendCapMicro: Math.round(parseCapUsd(from.DAILY_SPEND_CAP_USD, 2) * 1_000_000),
54|  };
55|}

