1|import "server-only";
2|import { createHmac } from "node:crypto";
3|import { QUOTA_TTL_SEC, overQuota, quotaKeys } from "@/core/images";
4|import type { KV } from "@/core/images";
5|
6|// Per-person quota: 5 new images per day, counted by hashed IP and by
7|// anonymous cookie, whichever runs out first. Day keys are UTC dates.
8|export function utcDay(now: Date = new Date()): string {
9|  return now.toISOString().slice(0, 10);
10|}
11|
12|export function hashIp(ip: string, salt: string): string {
13|  return createHmac("sha256", salt).update(ip).digest("hex");
14|}
15|
16|export function clientIp(forwardedFor: string | null | undefined): string {
17|  return (forwardedFor ?? "").split(",")[0]?.trim() || "unknown";
18|}
19|
20|export async function checkQuota(
21|  kv: KV,
22|  keys: { ip: string; anon: string },
23|): Promise<{ ok: true } | { ok: false }> {
24|  const ipCount = await kv.incr(keys.ip);
25|  await kv.expire(keys.ip, QUOTA_TTL_SEC);
26|  const anonCount = await kv.incr(keys.anon);
27|  await kv.expire(keys.anon, QUOTA_TTL_SEC);
28|  if (overQuota(ipCount) || overQuota(anonCount)) {
29|    await kv.decr(keys.ip);
30|    await kv.decr(keys.anon);
31|    return { ok: false };
32|  }
33|  return { ok: true };
34|}
35|
36|export async function refundQuota(kv: KV, keys: { ip: string; anon: string }): Promise<void> {
37|  await kv.decr(keys.ip);
38|  await kv.decr(keys.anon);
39|}
40|
41|export function quotaKeysFor(args: { day: string; ip: string; salt: string; anonId: string }): {
42|  ip: string;
43|  anon: string;
44|} {
45|  return quotaKeys({ day: args.day, ipHash: hashIp(args.ip, args.salt), anonId: args.anonId });
46|}
47|
48|// Free uploaded-book processing: one book per person for the whole
49|// hackathon. Keys carry no day so the limit never resets; the TTL (~10
50|// days) only bounds Redis growth. No route or wiring yet, just the hook.
51|export const FREE_BOOKS_PER_PERSON = 1;
52|export const BOOK_QUOTA_TTL_SEC = 10 * 24 * 3600;
53|
54|export function bookQuotaKeys(args: { ipHash: string; anonId: string }): {
55|  ip: string;
56|  anon: string;
57|} {
58|  return {
59|    ip: `books:quota:ip:${args.ipHash}`,
60|    anon: `books:quota:anon:${args.anonId}`,
61|  };
62|}
63|
64|export function bookQuotaKeysFor(args: { ip: string; salt: string; anonId: string }): {
65|  ip: string;
66|  anon: string;
67|} {
68|  return bookQuotaKeys({ ipHash: hashIp(args.ip, args.salt), anonId: args.anonId });
69|}
70|
71|export async function checkBookQuota(
72|  kv: KV,
73|  keys: { ip: string; anon: string },
74|): Promise<{ ok: true } | { ok: false }> {
75|  const ipCount = await kv.incr(keys.ip);
76|  await kv.expire(keys.ip, BOOK_QUOTA_TTL_SEC);
77|  const anonCount = await kv.incr(keys.anon);
78|  await kv.expire(keys.anon, BOOK_QUOTA_TTL_SEC);
79|  if (ipCount > FREE_BOOKS_PER_PERSON || anonCount > FREE_BOOKS_PER_PERSON) {
80|    await kv.decr(keys.ip);
81|    await kv.decr(keys.anon);
82|    return { ok: false };
83|  }
84|  return { ok: true };
85|}
86|
87|export async function refundBookQuota(kv: KV, keys: { ip: string; anon: string }): Promise<void> {
88|  await kv.decr(keys.ip);
89|  await kv.decr(keys.anon);
90|}

