1|export const MAX_IMAGE_BODY_BYTES = 8192 as const;
2|
3|export type CappedBody =
4|  | { ok: true; text: string }
5|  | { ok: false; reason: "too_large" | "read_error" };
6|
7|// Bounds how much of the request body we buffer before parsing: reject early
8|// on a lying-or-honest oversize content-length, then enforce a hard byte limit
9|// while streaming so a missing header can't bypass the cap.
10|export async function readBodyCapped(
11|  req: Pick<Request, "headers" | "body">,
12|  limit: number = MAX_IMAGE_BODY_BYTES,
13|): Promise<CappedBody> {
14|  const declared = req.headers.get("content-length");
15|  if (declared !== null) {
16|    const n = Number.parseInt(declared.trim(), 10);
17|    if (Number.isSafeInteger(n) && n > limit) return { ok: false, reason: "too_large" };
18|  }
19|  if (req.body === null) return { ok: true, text: "" };
20|  try {
21|    const reader = req.body.getReader();
22|    const chunks: Uint8Array[] = [];
23|    let total = 0;
24|    for (;;) {
25|      const { done, value } = await reader.read();
26|      if (done) break;
27|      total += value.byteLength;
28|      if (total > limit) {
29|        await reader.cancel().catch(() => {});
30|        return { ok: false, reason: "too_large" };
31|      }
32|      chunks.push(value);
33|    }
34|    const buf = new Uint8Array(total);
35|    let offset = 0;
36|    for (const chunk of chunks) {
37|      buf.set(chunk, offset);
38|      offset += chunk.byteLength;
39|    }
40|    return { ok: true, text: new TextDecoder().decode(buf) };
41|  } catch {
42|    return { ok: false, reason: "read_error" };
43|  }
44|}

