29|// anything else (missing, blank, non-numeric, negative, Infinity) falls back.
30|// Zero stays valid so a zero cap can intentionally block spend.
31|function parseCapUsd(raw: string | undefined, fallback: number): number {
32|  if (raw === undefined || raw.trim() === "") return fallback;
33|  const value = Number(raw);
